const inputOriginal = $input.first().json;
const body = inputOriginal.body ?? inputOriginal;

function pick(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return null;
}

function cleanText(value) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/^=/, '').trim();
}

// Estrutura variável conforme evento/versão da Evolution.
// Mantemos extração tolerante.
const data = body.data ?? body;

const mensagem =
  pick(
    data?.message?.conversation,
    data?.message?.extendedTextMessage?.text,
    data?.text,
    body?.message,
    body?.mensagem
  ) || '';

const telefone =
  pick(
    data?.key?.remoteJid,
    data?.remoteJid,
    data?.from,
    body?.from,
    body?.telefone
  ) || '';

const nomeContato =
  pick(
    data?.pushName,
    data?.senderName,
    body?.pushName,
    body?.nome_contato
  ) || null;

const instance =
  pick(
    body?.instance,
    body?.instanceName,
    data?.instance,
    data?.instanceName
  ) || null;

const mensagemLower = cleanText(mensagem).toLowerCase();

// Regra simples de obra: se não vier no texto, usa padrão MVP
let obraCodigo = 'OBRA-001';
const obraMatch = mensagem.match(/OBRA[-_\s]?\d+/i);
if (obraMatch) {
  obraCodigo = obraMatch[0].replace(/\s+/g, '-').toUpperCase();
}

// Classificação simples de rota
let tipo_entrada = 'MENSAGEM_GERAL';

if (
  mensagemLower.includes('relatório diário') ||
  mensagemLower.includes('relatorio diario') ||
  mensagemLower.includes('rdo') ||
  mensagemLower.includes('hoje executamos') ||
  mensagemLower.includes('foram executados')
) {
  tipo_entrada = 'RELATO_RDO';
}

if (
  mensagemLower.includes('pendência') ||
  mensagemLower.includes('pendencia') ||
  mensagemLower.includes('não foram enviadas fotos') ||
  mensagemLower.includes('nao foram enviadas fotos') ||
  mensagemLower.includes('necessário confirmar') ||
  mensagemLower.includes('necessario confirmar')
) {
  // Se for relato de RDO com pendência, deixamos como RELATO_RDO,
  // porque o Agente 02 já aciona o Agente 03.
  if (tipo_entrada !== 'RELATO_RDO') {
    tipo_entrada = 'PENDENCIA';
  }
}

return [
  {
    json: {
      canal: 'WHATSAPP',
      instance,
      telefone_origem: telefone,
      nome_contato: nomeContato,
      obra_codigo: obraCodigo,
      mensagem: cleanText(mensagem),
      tipo_entrada,
      possui_anexo: Boolean(data?.message?.imageMessage || data?.message?.documentMessage || data?.message?.audioMessage),
      payload_original: inputOriginal,
      data_recebimento: new Date().toISOString()
    }
  }
];

const crypto = require('crypto');

const item = $input.first().json;

/**
 * Retorna texto normalizado.
 */
function cleanText(value) {
  if (value === undefined || value === null) return '';

  return String(value)
    .replace(/^=/, '')
    .trim();
}

/**
 * Normaliza texto para geração de hash.
 */
function normalizeForHash(value) {
  return cleanText(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

/**
 * Gera SHA-256 hexadecimal.
 */
function sha256(value) {
  return crypto
    .createHash('sha256')
    .update(String(value), 'utf8')
    .digest('hex');
}

// Preserva compatibilidade com payload bruto ou já normalizado.
const payloadOriginal =
  item.payload_original ||
  item.entrada_original ||
  item;

const body = payloadOriginal.body || payloadOriginal;
const data = body.data || body;
const key = data.key || {};

const instance = cleanText(
  body.instance ||
  item.instance ||
  'obra-caio'
);

const messageId = cleanText(
  key.id ||
  data.messageId ||
  body.messageId ||
  item.message_id
);

const remoteJid = cleanText(
  key.remoteJid ||
  item.telefone_origem ||
  item.remote_jid
);

const obraCodigo = cleanText(
  item.obra_codigo ||
  body.obra_codigo
);

const tipoEntrada = cleanText(
  item.tipo_entrada
);

const mensagem = cleanText(
  item.mensagem ||
  data.message?.conversation ||
  data.message?.extendedTextMessage?.text ||
  data.message?.imageMessage?.caption ||
  data.message?.documentMessage?.caption
);

// O hash ignora timestamp de recebimento para que a mesma mensagem
// produza sempre a mesma identificação.
const payloadCanonico = JSON.stringify({
  instance,
  message_id: messageId || null,
  remote_jid: remoteJid || null,
  obra_codigo: obraCodigo || null,
  tipo_entrada: tipoEntrada || null,
  mensagem: normalizeForHash(mensagem)
});

const payloadHash = sha256(payloadCanonico);

// Prioridade: ID real da Evolution.
// Fallback: hash do conteúdo normalizado.
const baseIdempotencia = messageId
  ? `WHATSAPP|${instance}|${messageId}`
  : `WHATSAPP|${instance}|${remoteJid}|${payloadHash}`;

const idempotencyKey =
  `WA_${sha256(baseIdempotencia)}`.slice(0, 128);

return [
  {
    json: {
      ...item,

      evolution_instance: instance,
      evolution_message_id: messageId || null,

      idempotency_key: idempotencyKey,
      correlation_id: crypto.randomUUID(),
      payload_hash: payloadHash,

      idempotency_source: messageId
        ? 'EVOLUTION_MESSAGE_ID'
        : 'PAYLOAD_HASH'
    }
  }
];

const item = $input.first().json;

function parseBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;

  return ['true', 't', '1', 'sim', 'yes'].includes(
    String(value ?? '').trim().toLowerCase()
  );
}

return [
  {
    json: {
      evento_id: item.evento_id || null,
      idempotency_key: item.idempotency_key || null,

      correlation_id:
        item.correlation_id_evento || null,

      obra_codigo: item.obra_codigo || null,
      tipo_entrada: item.tipo_entrada || null,
      mensagem: item.mensagem || null,
      payload_hash: item.payload_hash || null,

      evento_status: item.evento_status || null,
      evento_criado_em: item.evento_criado_em || null,
      evento_novo: parseBoolean(item.evento_novo)
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      status: 'ja_processado',
      duplicado: true,
      obra_codigo: item.obra_codigo || null,
      tipo_entrada: item.tipo_entrada || null,
      evento_id: item.evento_id || null,
      idempotency_key: item.idempotency_key || null,
      correlation_id: item.correlation_id || null,
      mensagem: 'Este evento já havia sido processado anteriormente.'
    }
  }
];

const respostaFinal = $input.first().json;

// Recupera os identificadores da mesma execução
const evento = $('Consolidar Idempotência').first().json;

return [
  {
    json: {
      idempotency_key: evento.idempotency_key || null,
      correlation_id: evento.correlation_id || null,
      evento_id: evento.evento_id || null,

      obra_codigo:
        respostaFinal.obra_codigo ||
        evento.obra_codigo ||
        null,

      tipo_entrada:
        evento.tipo_entrada ||
        null,

      resposta_final: respostaFinal
    }
  }
];

const respostaAgente = $input.first().json;

// Ajuste o nome se o seu nó tiver outro nome
const entrada = $items("Normalizar WhatsApp")[0].json;

return [
  {
    json: {
      status: "whatsapp_processado",
      tipo_entrada: entrada.tipo_entrada,
      obra_codigo: entrada.obra_codigo,
      canal: entrada.canal,
      telefone_origem: entrada.telefone_origem,
      nome_contato: entrada.nome_contato,
      mensagem: "Mensagem recebida e encaminhada pelo Agente 00.",
      resposta_agente_destino: respostaAgente
    }
  }
];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();
